#!/usr/bin/env python3
from pwn import *
import base64
import threading
import queue
import time
import string
import re

# Settings
host = "crypto.chal.csaw.io"
port = 6000
BLOCK_SIZE = 16
TIMEOUT = 2
MAX_RETRIES = 15
DELAY = 0.5

# Connection pool
conn_pool = queue.Queue(maxsize=5)
conn_lock = threading.Lock()

# Cache for oracle responses
oracle_cache = {}
oracle_cache_lock = threading.Lock()

def get_connection():
    try:
        # Try to get a connection from the pool
        return conn_pool.get_nowait()
    except queue.Empty:
        return new_connection()

def return_connection(conn):
    try:
        if conn and not conn.closed:
            conn_pool.put_nowait(conn)
        else:
            if conn:
                conn.close()
    except:
        if conn:
            conn.close()

def new_connection():
    for _ in range(MAX_RETRIES):
        try:
            r = remote(host, port, timeout=TIMEOUT)
            time.sleep(DELAY)
            r.recvuntil(b"Choice> ", timeout=TIMEOUT)
            return r
        except:
            if 'r' in locals() and r:
                r.close()
            time.sleep(DELAY)
    return None

def oracle(ct):
    cache_key = ct.hex()

    with oracle_cache_lock:
        if cache_key in oracle_cache:
            return oracle_cache[cache_key]

    for _ in range(MAX_RETRIES):
        conn = None
        try:
            conn = get_connection()
            if not conn:
                continue

            conn.clean()
            conn.sendline(b"2")
            time.sleep(DELAY)
            conn.clean()
            conn.sendline(base64.b64encode(ct))
            response = conn.recvuntil([b"Invalid padding", b"Valid padding"], timeout=TIMEOUT)

            valid = b"Valid" in response
            with oracle_cache_lock:
                oracle_cache[cache_key] = valid

            return_connection(conn)
            return valid

        except Exception as e:
            log.debug(f"Oracle error: {e}")
            if conn:
                conn.close()
            time.sleep(DELAY)

    return False

def get_fresh_ciphertext():
    for _ in range(MAX_RETRIES):
        conn = None
        try:
            conn = get_connection()
            if not conn:
                continue

            conn.clean()
            conn.sendline(b"1")
            time.sleep(DELAY)
            conn.recvuntil(b"Enter your poodle's name> ")
            conn.sendline(b"A" * 8)  # Short name to minimize padding
            time.sleep(DELAY)
            conn.recvuntil(b"Enter choice> ")
            conn.sendline(b"1")

            response = conn.recvuntil(b"Choice> ").decode()
            conn.close()

            for line in response.split('\n'):
                if "reads:" in line:
                    ct_b64 = line.split("reads: ")[1].strip()
                    return base64.b64decode(ct_b64)

        except Exception as e:
            log.debug(f"Get ciphertext error: {e}")
            if conn:
                conn.close()
            time.sleep(DELAY)

    raise Exception("Failed to get fresh ciphertext")

def decrypt_block(ct, block_num):
    log.info(f"Decrypting block {block_num}")

    iv = ct[block_num*BLOCK_SIZE:(block_num+1)*BLOCK_SIZE]
    target = ct[(block_num+1)*BLOCK_SIZE:(block_num+2)*BLOCK_SIZE]
    intermediate = [0] * BLOCK_SIZE
    plaintext = [0] * BLOCK_SIZE

    # Precompute byte sets for efficiency
    COMMON_BYTES = bytes(range(32, 127))  # printable ASCII
    ALL_BYTES = bytes(range(256))

    for byte_num in range(BLOCK_SIZE-1, -1, -1):
        pad_value = BLOCK_SIZE - byte_num
        working_iv = bytearray(iv)

        # Set padding bytes
        for i in range(byte_num + 1, BLOCK_SIZE):
            working_iv[i] ^= intermediate[i] ^ pad_value

        # First try printable ASCII, then try all bytes
        found = False
        for byte_set in [COMMON_BYTES, ALL_BYTES]:
            for guess in byte_set:
                working_iv[byte_num] = guess
                if oracle(bytes(working_iv) + target):
                    intermediate_byte = guess ^ iv[byte_num] ^ pad_value
                    intermediate[byte_num] = intermediate_byte
                    plaintext[byte_num] = intermediate_byte ^ iv[byte_num]
                    found = True
                    log.info(f"Found byte {byte_num}: {hex(plaintext[byte_num])[2:].zfill(2)}")

                    # Show ASCII if printable
                    if 32 <= plaintext[byte_num] <= 126:
                        log.info(f"ASCII: '{chr(plaintext[byte_num])}'")

                    break
            if found:
                break

        if not found:
            log.error(f"Failed to find byte {byte_num}")
            return None

        # Progress report
        if byte_num % 4 == 0:
            try:
                partial = bytes(plaintext[byte_num:])
                log.info(f"Partial decryption: {partial.hex()} | {partial.decode(errors='replace')}")
            except:
                pass

    return bytes(plaintext)

def main():
    context.log_level = 'info'

    try:
        # Initialize connection pool
        for _ in range(3):
            conn = new_connection()
            if conn:
                return_connection(conn)

        log.info("Getting fresh ciphertext...")
        ct = get_fresh_ciphertext()
        if not ct:
            log.error("Failed to get ciphertext")
            return None

        log.info(f"Ciphertext (len={len(ct)}): {ct.hex()}")

        num_blocks = len(ct) // BLOCK_SIZE - 1
        log.info(f"Number of blocks to decrypt: {num_blocks}")

        plaintext = bytearray()

        for block in range(num_blocks):
            block_pt = decrypt_block(ct, block)
            if block_pt is None:
                log.error(f"Failed to decrypt block {block}")
                return None

            plaintext.extend(block_pt)
            log.info(f"\nDecrypted block {block}: {block_pt.hex()}")

            try:
                ascii_block = ''.join(chr(c) if 32 <= c <= 126 else '.' for c in block_pt)
                log.info(f"ASCII: {ascii_block}")
            except:
                pass

        final_pt = bytes(plaintext)
        log.info(f"\nFinal plaintext: {final_pt.hex()}")

        try:
            ascii_text = ''.join(chr(c) if 32 <= c <= 126 else '.' for c in final_pt)
            log.info(f"ASCII: {ascii_text}")
        except:
            pass

        # Look for flag
        flag_start = final_pt.find(b"flag{")
        if flag_start != -1:
            flag_end = final_pt.find(b"}", flag_start) + 1
            flag = final_pt[flag_start:flag_end].decode()
            log.success(f"Found flag: {flag}")
            return flag

        # Alternative flag format search
        flag_pattern = re.compile(b'flag{[^}]+}')
        flag_match = flag_pattern.search(final_pt)
        if flag_match:
            flag = flag_match.group(0).decode()
            log.success(f"Found flag (pattern): {flag}")
            return flag

        log.error("No flag found in decrypted data")
        return None

    except Exception as e:
        log.error(f"Error during attack: {str(e)}")
        return None
    finally:
        # Cleanup
        while not conn_pool.empty():
            try:
                conn = conn_pool.get_nowait()
                if conn:
                    conn.close()
            except:
                pass

if __name__ == "__main__":
    main()

from pwn import *
import base64
import time

host = "crypto.chal.csaw.io"
port = 6000
TIMEOUT = 5
MAX_RETRIES = 3
DELAY = 0.1

context.log_level = 'info'

def safe_recv(conn, expected=None, timeout=TIMEOUT):
    try:
        if expected:
            return conn.recvuntil(expected, timeout=timeout)
        return conn.recv(timeout=timeout)
    except EOFError:
        return None

def create_connection():
    for _ in range(MAX_RETRIES):
        try:
            conn = remote(host, port, timeout=TIMEOUT)
            return conn
        except Exception:
            time.sleep(DELAY)
    return None

def oracle(ct):
    for _ in range(MAX_RETRIES):
        conn = None
        try:
            conn = create_connection()
            if not conn:
                continue

            if not safe_recv(conn, b"> "):
                continue

            conn.sendline(b"2")  # Decrypt option
            if not safe_recv(conn, b"> "):
                continue

            b64_ct = base64.b64encode(ct)
            conn.sendline(b64_ct)

            response = safe_recv(conn, b"> ")
            if not response:
                continue

            time.sleep(DELAY)
            response = response.decode()

            if "Error" in response or "Invalid" in response:
                return False
            return True

        except Exception as e:
            continue
        finally:
            if conn:
                conn.close()
            time.sleep(DELAY)
    return False

def get_block():
    for _ in range(MAX_RETRIES):
        conn = None
        try:
            conn = create_connection()
            if not conn:
                continue

            if not safe_recv(conn, b"> "):
                continue

            conn.sendline(b"1")  # Shop option
            if not safe_recv(conn, b"> "):
                continue

            conn.sendline(b"1")  # Order poodle
            if not safe_recv(conn, b"> "):
                continue

            conn.sendline(b"1")  # Quantity = 1

            response = safe_recv(conn, b"> ")
            if not response:
                continue

            response = response.decode()
            for line in response.split('\n'):
                if "banner that reads:" in line:
                    b64_data = line.split("reads: ")[1].strip()
                    return base64.b64decode(b64_data)
        except Exception:
            continue
        finally:
            if conn:
                conn.close()
            time.sleep(DELAY)
    return None

def find_byte(ct_block, iv_block, padding_val, known_bytes):
    iv_test = bytearray(iv_block)

    # Set up padding bytes
    for i, known_byte in enumerate(known_bytes):
        iv_test[-(i+1)] ^= known_byte ^ padding_val

    # Try each possible byte
    target_pos = len(iv_block) - len(known_bytes) - 1
    for guess in range(32, 127):  # ASCII printable range
        test_iv = bytearray(iv_test)
        test_iv[target_pos] ^= guess ^ padding_val

        if oracle(bytes(test_iv) + ct_block):
            return guess ^ padding_val ^ iv_block[target_pos]
    return None

def attack_block(ct_block, iv_block):
    plaintext = bytearray([0] * 16)
    known_bytes = []

    for i in range(1, 17):  # For each byte position
        padding_val = i
        pos = 16 - i
        log.info(f"Trying position {pos} (padding {padding_val})")

        found = find_byte(ct_block, iv_block, padding_val, known_bytes)
        if found is not None:
            plaintext[pos] = found
            known_bytes.insert(0, found)

            partial = bytes(plaintext)
            log.success(f"Found byte at pos {pos}: {chr(found)} ({found:02x})")
            log.info(f"Current plaintext: {partial}")
        else:
            partial = bytes(plaintext)
            log.info(f"Failed at pos {pos}. Current: {partial}")
            return partial

    return bytes(plaintext)

def main():
    log.info("Getting initial block...")
    full_ct = get_block()
    if not full_ct:
        log.error("Failed to get initial block")
        return

    blocks = [full_ct[i:i+16] for i in range(0, len(full_ct), 16)]
    iv = blocks[0]
    first = blocks[1]

    log.info(f"IV: {iv.hex()}")
    log.info(f"First block: {first.hex()}")

    result = attack_block(first, iv)
    if result:
        log.success(f"Decrypted block: {result}")

if __name__ == "__main__":
    main()

